#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int height, number;
    cin >> height >> number;
    number -= 1;

    string bin_str;
    {
        stringstream ss;
        ss << std::bitset<32>(number);
        bin_str = ss.str();
        // Remove leading zeros
        size_t pos = bin_str.find('1');
        if (pos != string::npos) {
            bin_str = bin_str.substr(pos);
        } else {
            bin_str = "0";
        }
    }

    // Pad with zeros to match height
    if ((int)bin_str.size() < height) {
        bin_str = string(height - bin_str.size(), '0') + bin_str;
    }

    string output_str = "";
    for (int position = 0; position < height; ++position) {
        if (position != 0 && bin_str[position - 1] == '0') {
            output_str += (bin_str[position] == '0') ? '1' : '0';
        } else {
            output_str += bin_str[position];
        }
    }

    long long total_sum = 0;
    for (int position = 0; position < height; ++position) {
        total_sum += 1;
        if (output_str[position] == '1') {
            total_sum += (1LL << (height - position)) - 1;
        }
    }

    cout << total_sum << "\n";

    return 0;
}
